 $_REQUEST['uniquesession'] = true; require_once(__DIR__ . '../../../../app/init.php'); class med_vaccinations_recoveryRemovedVaccinacions { private $db1; private $db2; private $db1Name; private $db2Name; private $dateBeforeDeletion; private $dateAfterDeletion; public function __construct() { $this->db1 = new PDO( 'pgsql:host=127.0.0.1;port=5432;dbname=mapdb;user=map;password=pam' ); $this->db2 = new PDO( 'pgsql:host=127.0.0.1;port=5432;dbname=mapdb2;user=map;password=pam' ); $this->db1Name = $this->db1->query("SELECT current_database()")->fetchColumn(); $this->db2Name = $this->db2->query("SELECT current_database()")->fetchColumn(); $this->dateBeforeDeletion = '2024-01-31'; $this->dateAfterDeletion = '2025-02-11'; } public function readLog($params = []) { print "--- readLog() started ---\n"; try { print "Реальное подключение DB1: {$this->db1Name}\n"; print "Реальное подключение DB2: {$this->db2Name}\n"; $sql = <<<SQL
